+import { createEventCard } from './event-card.js';
+
+function buildAgendaEntries(events) {
+  return events.map((event) => ({
+    event,
+    card: createEventCard(event),
+    timestamp: new Date(event.startsAt).getTime(),
+  })).sort((a, b) => a.timestamp - b.timestamp);
+}
